using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Produktionsplanung.App.Models;
using Produktionsplanung.App.Services;
namespace Produktionsplanung.App.Data;
public class AppDbContext:DbContext{
 public DbSet<Employee> Employees=>Set<Employee>();public DbSet<Qualification> Qualifications=>Set<Qualification>();public DbSet<EmployeeQualification> EmployeeQualifications=>Set<EmployeeQualification>();public DbSet<Workstation> Workstations=>Set<Workstation>();public DbSet<Shift> Shifts=>Set<Shift>();public DbSet<WorkstationShiftRule> WorkstationShiftRules=>Set<WorkstationShiftRule>();public DbSet<Absence> Absences=>Set<Absence>();public DbSet<OperatingCalendarDay> OperatingCalendarDays=>Set<OperatingCalendarDay>();public DbSet<WorkTimeEntry> WorkTimeEntries=>Set<WorkTimeEntry>();public DbSet<PlanningAssignment> PlanningAssignments=>Set<PlanningAssignment>();public DbSet<ProductionOrder> ProductionOrders=>Set<ProductionOrder>();public DbSet<ProductionRunSlot> ProductionRunSlots=>Set<ProductionRunSlot>();public DbSet<ProductionActual> ProductionActuals=>Set<ProductionActual>();public DbSet<DowntimeEntry> DowntimeEntries=>Set<DowntimeEntry>();public DbSet<OperationDefinition> OperationDefinitions=>Set<OperationDefinition>();public DbSet<ManufacturingRouting> ManufacturingRoutings=>Set<ManufacturingRouting>();public DbSet<RoutingStep> RoutingSteps=>Set<RoutingStep>();public DbSet<JobCard> JobCards=>Set<JobCard>();public DbSet<UserAccount> UserAccounts=>Set<UserAccount>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();
 protected override void OnConfiguring(DbContextOptionsBuilder b){AppPaths.EnsureDirectories();b.UseSqlite($"Data Source={AppPaths.DatabasePath}");}
 protected override void OnModelCreating(ModelBuilder m){m.Entity<Employee>().HasIndex(x=>x.PersonnelNumber).IsUnique();m.Entity<EmployeeQualification>().HasKey(x=>new{x.EmployeeId,x.QualificationId});m.Entity<EmployeeQualification>().HasOne(x=>x.Employee).WithMany(x=>x.Qualifications).HasForeignKey(x=>x.EmployeeId);m.Entity<EmployeeQualification>().HasOne(x=>x.Qualification).WithMany(x=>x.Employees).HasForeignKey(x=>x.QualificationId);m.Entity<Workstation>().HasOne(x=>x.RequiredQualification).WithMany().HasForeignKey(x=>x.RequiredQualificationId).OnDelete(DeleteBehavior.SetNull);m.Entity<WorkstationShiftRule>().HasIndex(x=>new{x.WorkstationId,x.ShiftId}).IsUnique();m.Entity<WorkstationShiftRule>().HasOne(x=>x.Workstation).WithMany(x=>x.ShiftRules).HasForeignKey(x=>x.WorkstationId).OnDelete(DeleteBehavior.Cascade);m.Entity<WorkstationShiftRule>().HasOne(x=>x.Shift).WithMany().HasForeignKey(x=>x.ShiftId).OnDelete(DeleteBehavior.Restrict);m.Entity<OperatingCalendarDay>().HasIndex(x=>x.Date).IsUnique();m.Entity<WorkTimeEntry>().HasIndex(x=>new{x.EmployeeId,x.Date});m.Entity<WorkTimeEntry>().HasOne(x=>x.Employee).WithMany().HasForeignKey(x=>x.EmployeeId).OnDelete(DeleteBehavior.Restrict);m.Entity<ProductionOrder>().HasIndex(x=>x.OrderNumber).IsUnique();m.Entity<ProductionOrder>().HasIndex(x=>new{x.PlannedDate,x.WorkstationId,x.ShiftId});m.Entity<ProductionOrder>().HasOne(x=>x.Workstation).WithMany().HasForeignKey(x=>x.WorkstationId).OnDelete(DeleteBehavior.Restrict);m.Entity<ProductionOrder>().HasOne(x=>x.Shift).WithMany().HasForeignKey(x=>x.ShiftId).OnDelete(DeleteBehavior.SetNull);m.Entity<ProductionRunSlot>().HasIndex(x=>new{x.ProductionOrderId,x.SequenceNumber}).IsUnique();m.Entity<ProductionRunSlot>().HasIndex(x=>new{x.Date,x.ShiftId});m.Entity<ProductionRunSlot>().HasOne(x=>x.ProductionOrder).WithMany(x=>x.RunSlots).HasForeignKey(x=>x.ProductionOrderId).OnDelete(DeleteBehavior.Cascade);m.Entity<ProductionRunSlot>().HasOne(x=>x.Shift).WithMany().HasForeignKey(x=>x.ShiftId).OnDelete(DeleteBehavior.Restrict);m.Entity<ProductionActual>().HasIndex(x=>new{x.ProductionOrderId,x.Date});m.Entity<ProductionActual>().HasIndex(x=>x.ProductionRunSlotId);m.Entity<ProductionActual>().HasOne(x=>x.ProductionOrder).WithMany(x=>x.Actuals).HasForeignKey(x=>x.ProductionOrderId).OnDelete(DeleteBehavior.Cascade);m.Entity<ProductionActual>().HasOne(x=>x.ProductionRunSlot).WithMany(x=>x.Actuals).HasForeignKey(x=>x.ProductionRunSlotId).OnDelete(DeleteBehavior.Restrict);m.Entity<DowntimeEntry>().HasIndex(x=>x.ProductionActualId);m.Entity<DowntimeEntry>().HasOne(x=>x.ProductionActual).WithMany(x=>x.Downtimes).HasForeignKey(x=>x.ProductionActualId).OnDelete(DeleteBehavior.Cascade);m.Entity<OperationDefinition>().HasIndex(x=>x.Code).IsUnique();m.Entity<OperationDefinition>().HasOne(x=>x.DefaultWorkstation).WithMany().HasForeignKey(x=>x.DefaultWorkstationId).OnDelete(DeleteBehavior.SetNull);m.Entity<OperationDefinition>().HasOne(x=>x.RequiredQualification).WithMany().HasForeignKey(x=>x.RequiredQualificationId).OnDelete(DeleteBehavior.SetNull);m.Entity<ManufacturingRouting>().HasIndex(x=>x.Product);m.Entity<RoutingStep>().HasIndex(x=>new{x.ManufacturingRoutingId,x.SequenceNumber}).IsUnique();m.Entity<RoutingStep>().HasOne(x=>x.ManufacturingRouting).WithMany(x=>x.Steps).HasForeignKey(x=>x.ManufacturingRoutingId).OnDelete(DeleteBehavior.Cascade);m.Entity<RoutingStep>().HasOne(x=>x.OperationDefinition).WithMany(x=>x.RoutingSteps).HasForeignKey(x=>x.OperationDefinitionId).OnDelete(DeleteBehavior.Restrict);m.Entity<RoutingStep>().HasOne(x=>x.Workstation).WithMany().HasForeignKey(x=>x.WorkstationId).OnDelete(DeleteBehavior.Restrict);m.Entity<JobCard>().HasIndex(x=>new{x.ProductionOrderId,x.SequenceNumber}).IsUnique();m.Entity<JobCard>().HasIndex(x=>new{x.WorkstationId,x.Status});m.Entity<JobCard>().HasOne(x=>x.ProductionOrder).WithMany().HasForeignKey(x=>x.ProductionOrderId).OnDelete(DeleteBehavior.Cascade);m.Entity<JobCard>().HasOne(x=>x.RoutingStep).WithMany().HasForeignKey(x=>x.RoutingStepId).OnDelete(DeleteBehavior.SetNull);m.Entity<JobCard>().HasOne(x=>x.Workstation).WithMany().HasForeignKey(x=>x.WorkstationId).OnDelete(DeleteBehavior.Restrict);m.Entity<JobCard>().HasOne(x=>x.Employee).WithMany().HasForeignKey(x=>x.EmployeeId).OnDelete(DeleteBehavior.SetNull);m.Entity<UserAccount>().HasIndex(x=>x.Username).IsUnique();m.Entity<AuditLog>().HasIndex(x=>x.TimestampUtc);m.Entity<AuditLog>().HasIndex(x=>x.Username);}
 public override int SaveChanges(){var s=CaptureAuditSnapshots();var r=base.SaveChanges();WriteAuditSnapshots(s);return r;}private List<AuditSnapshot> CaptureAuditSnapshots(){if(!SessionService.IsAuthenticated)return new();var s=new List<AuditSnapshot>();foreach(var e in ChangeTracker.Entries().Where(x=>x.Entity is not AuditLog&&x.State is EntityState.Added or EntityState.Modified or EntityState.Deleted)){var mod=e.State==EntityState.Modified?e.Properties.Where(x=>x.IsModified&&x.Metadata.Name is not nameof(UserAccount.PasswordHash) and not nameof(UserAccount.PasswordSalt)).Select(x=>x.Metadata.Name).ToArray():Array.Empty<string>();s.Add(new(e,e.State,GetEntityId(e),mod.Length==0?null:$"Geänderte Felder: {string.Join(", ",mod)}"));}return s;}private void WriteAuditSnapshots(List<AuditSnapshot>s){if(s.Count==0||SessionService.CurrentUser is null)return;foreach(var x in s){var id=x.State==EntityState.Added?GetEntityId(x.Entry):x.EntityIdBefore;AuditLogs.Add(new AuditLog{TimestampUtc=DateTime.UtcNow,Username=SessionService.CurrentUser.Username,Action=x.State switch{EntityState.Added=>"Erstellt",EntityState.Modified=>"Geändert",EntityState.Deleted=>"Gelöscht",_=>x.State.ToString()},EntityType=x.Entry.Metadata.ClrType.Name,EntityId=id,Details=x.Details});}base.SaveChanges();}private static string? GetEntityId(EntityEntry e){var k=e.Metadata.FindPrimaryKey();if(k is null)return null;var v=k.Properties.Select(p=>e.Property(p.Name).CurrentValue?.ToString()).Where(x=>!string.IsNullOrWhiteSpace(x));var r=string.Join("/",v);return string.IsNullOrWhiteSpace(r)?null:r;}private sealed record AuditSnapshot(EntityEntry Entry,EntityState State,string? EntityIdBefore,string? Details);
}
